// Exact multi-output single-stage static complementary CMOS synthesis.
//
// Model:
//   * every output is one complex static CMOS gate (PDN + dual PUN);
//   * the PDN is an exact minimum-literal sum of products of input literals;
//   * input complements are generated by shared 2T inverters;
//   * no pass transistors, no internal gate sharing, no multi-level gates.
//
// The optimizer enumerates every inverter subset (2^n) and, for each output,
// finds an exact minimum-literal DNF with the available literals.  It is
// therefore a proof of optimality inside this explicitly bounded model.
#pragma once

#include <cstdint>
#include <string>
#include <vector>

#include "dcstudy/boolfunc.hpp"
#include "dcstudy/cdl.hpp"
#include "dcstudy/cmos.hpp"

namespace dcstudy {

struct StaticExactResult {
  bool ok = false;
  bool proof = false;
  // How optimality was established: "exhaustive" (every inverter subset) or
  // "analytic_shortcut" (all outputs are single cubes, so the minimum is
  // fixed without enumerating the 2^n subsets).
  std::string proof_method;
  bool verified = false;
  std::string reason;
  int total = 0;
  int gate_cost = 0;
  int inverter_cost = 0;
  int nfet = 0;
  int pfet = 0;
  std::uint64_t inverted_mask = 0;  // bit i -> input i complemented
  std::vector<std::string> outputs;
  std::vector<Sop> pdn;             // parallel PDN terms for each output
  std::vector<std::string> truths;
  Subckt netlist;
  std::string cdl;
};

// Exact minimum DNF of `onset` over the available literals.  A negative
// literal for variable i is available iff bit i of `neg_allowed` is set.
// Returns false when no cover exists with those literals.
bool exact_min_dnf_literals(const Bits& onset, std::size_t n,
                            std::uint64_t neg_allowed, Sop& out);

StaticExactResult synthesize_static_exact_multi(
    const std::vector<BoolFunc>& funcs, const std::vector<std::string>& names,
    const std::vector<std::string>& vars);

}  // namespace dcstudy
